                        // type-confused callee would make the CallIndirect ill-typed.
                        if self.is_borrow_ptr(callee_val) {
                            self.unsupported.push((
                                format!("{expr_span:?}"),
                                "Call(fn-ptr callee unsupported)",
                            ));
                            return None;
                        }
